o1(){ . "$UT/fnpl.txt"; local q="$1" n root idx cand _n sel x p f d fs _arr var; [[ "$q" =~ ^([0-9])(.*)$ ]] && { n="${BASH_REMATCH[1]}"; q="${BASH_REMATCH[2]}"; } || n=0; var="f$n"; root="${!var}"; [ -z "$root" ] && return 0; idx="$FW/fnp/$n.txt"; [ -f "$idx" ] || return 0; if [[ "$q" == *[?~/] ]]; then lo2 f7.f6; cand=""; _n=""; while IFS=: read -r d fs; do IFS=, read -ra _arr <<<"$fs"; for f in "${_arr[@]}"; do [ -z "$f" ] && continue; cand+="$f"$'\t'"$root/$d/$f"$'\n'; _n+="$f"$'\n'; done; done <"$idx"; cf0 sel f6 "$q" <<<"$_n"; [ -n "$sel" ] && while IFS=$'\t' read -r x p; do [ "$x" = "$sel" ] && { echo "$p"; break; }; done <<<"$cand"; else while IFS=: read -r d fs; do IFS=, read -ra _arr <<<"$fs"; for f in "${_arr[@]}"; do [ -z "$f" ] && continue; if [[ "$q" == *.* ]]; then [ "$f" = "$q" ] && { echo "$root/$d/$f"; return 0; }; else [[ "$f" == "$q".* ]] && { echo "$root/$d/$f"; return 0; }; fi; done; done <"$idx"; fi; return 0; }
is(){ case $# in 1) [ -n "${!1}" ];; 2) [[ "$1" == $2 ]];; *) return 1;; esac; }
gf="$FW/fnp";cf="$UT/fnpl.txt"; . "$cf" ;
case "$1" in i) shift; p(){ local r="$1" o="$2" d="$3"; >"$o"; find "$r" -mindepth 1 -maxdepth "$d" -type d|while IFS= read -r x;do l="${x#$r/}"; f=$(find "$x" -maxdepth 1 -type f -printf "%f\n"|paste -sd,); [ -n "$f" ]&&echo "$l:$f,">>"$o";done;}; a="${1:-0}"; n="${a%%.*}"; n="${n:-0}"; var="f$n"; r="${!var}"; [ -z "$r" ]&&exit 1; d="${a#$n}"; d="${d#.}"; [ -z "$d" ]&&d=3; o="$gf/$n.txt"; if [ "$n" = 0 ]&&[ -f "$o" ]; then oldroot="${f0}"; for m in 1 2 3 4; do midx="$gf/$m.txt"; mroot="$(eval echo \$f$m)"; [ -f "$midx" ]&&[ -n "$mroot" ]&&[ "$mroot" = "$oldroot" ]&&cp "$o" "$midx"; done; fi; p "$r" "$o" "$d"; sed -i "/^f${n}=/d" "$cf" 2>/dev/null; echo "f${n}=${r}" >> "$cf";;o) shift;o1 "$@";;
e) shift; p="$1"; op="$2"; for n in 0 1 2 3 4; do var="f$n"; r="${!var}"; idx="$gf/$n.txt"; [ -n "$r" ]&&[ -f "$idx" ]&&[[ "$p" == "$r"/* ]]&&{ root="$r"; rel="${p#$r/}"; break; }; done; [ -z "$root" ]&&exit 0; dir="${rel%/*}"; file="${rel##*/}"; case "${op:0:1}" in n) mapfile -t L<"$idx";found=0;for i in "${!L[@]}";do [[ "${L[i]}" == "$dir:"* ]]&&{ L[i]="${L[i]}$file,";found=1;break; };done;[ "$found" = 0 ]&&L+=("$dir:$file,");printf '%s\n' "${L[@]}">"$idx";; d) mapfile -t L<"$idx";out=();for l in "${L[@]}";do [[ "$l" == "$dir:"* ]]&&{ l="${l//"$file,"/}";[ "$l" = "$dir:" ]&&continue; };out+=("$l");done;printf '%s\n' "${out[@]}">"$idx";; r) n="${op:1}";! is "$n" '*.*'&&is "$file" '*.*'&&n="$n.${file##*.}";mapfile -t L<"$idx";for i in "${!L[@]}";do [[ "${L[i]}" == "$dir:"* ]]&&L[i]="${L[i]//"$file"/"$n"}";done;printf '%s\n' "${L[@]}">"$idx";; m) target="${op:1}";nidx="";nrel="";for m in 0 1 2 3 4;do var="f$m";mr="${!var}";midx="$gf/$m.txt";[ -n "$mr" ]&&[ -f "$midx" ]&&[[ "$target" == "$mr"/* ]]&&{ nidx="$midx";nrel="${target#$mr/}";break; };done;mapfile -t L<"$idx";out=();for l in "${L[@]}";do [[ "$l" == "$dir:"* ]]&&{ l="${l//"$file,"/}";[ "$l" = "$dir:" ]&&continue; };out+=("$l");done;printf '%s\n' "${out[@]}">"$idx";[ -z "$nidx" ]&&exit 0;nd="${nrel%/*}";mapfile -t L<"$nidx";found=0;for i in "${!L[@]}";do [[ "${L[i]}" == "$nd:"* ]]&&{ L[i]="${L[i]}$file,";found=1;break; };done;[ "$found" = 0 ]&&L+=("$nd:$file,");printf '%s\n' "${L[@]}">"$nidx";; esac;;
l) shift;if [ $# -eq 0 ];then out="";for n in 0 1 2 3;do var="f$n";[ -n "${!var}" ]&&out="$out $n";done;echo "${out# }";exit 0;fi;n="$1";var="f$n";if [ $# -eq 1 ];then [ -f "$gf/$n.txt" ]&&nvim "$gf/$n.txt"||echo "<no index: $n>";else path="$2";case "$path" in /*) ;; *) echo "<l" >&2; exit 1;; esac;sed -i "/^f${n}=/d" "$gf/l" 2>/dev/null;echo "f${n}=${path}" >> "$gf/l";"$0" i "$n";fi;;esac
